function sb6_secret(): string {$c=cc_config();return hash('sha256','surf-beta-v2|'.($c['db_pass']??'fallback').'|costacams');}
function sb6_token(int $id,string $email,string $purpose): string {$sig=hash_hmac('sha256',$id.'|'.$purpose.'|'.strtolower($email),sb6_secret());return rtrim(strtr(base64_encode($id.'|'.$purpose.'|'.$sig),'+/','-_'),'=');}
function sb6_http_json(string $url,int $timeout=12): ?array {if(!function_exists('curl_init'))return null;$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_CONNECTTIMEOUT=>4,CURLOPT_TIMEOUT=>$timeout,CURLOPT_USERAGENT=>'CostaCamsSurfBrief/6.0',CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_HTTPHEADER=>['Accept: application/json']]);$raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($raw===false||$code<200||$code>=400)return null;$j=json_decode((string)$raw,true);return is_array($j)?$j:null;}
function sb6_road_times(array $spots,array $p): array {if(!is_numeric($p['origin_lat']??null)||!is_numeric($p['origin_lon']??null))return [];$olat=(float)$p['origin_lat'];$olon=(float)$p['origin_lon'];$coords=[sprintf('%.5f,%.5f',$olon,$olat)];$slugs=[];$fallback=[];foreach($spots as $s){$slug=(string)$s['slug'];$slugs[]=$slug;$coords[]=sprintf('%.5f,%.5f',(float)$s['lon'],(float)$s['lat']);$fallback[$slug]=cc_surf_travel_minutes($olat,$olon,(float)$s['lat'],(float)$s['lon']);}$idx=range(1,count($slugs));$j=sb6_http_json('https://router.project-osrm.org/table/v1/driving/'.implode(';',$coords).'?sources=0&destinations='.implode(';',$idx).'&annotations=duration');if(!$j||($j['code']??'')!=='Ok'||empty($j['durations'][0]))return $fallback;$out=[];foreach($slugs as $i=>$slug){$sec=$j['durations'][0][$i]??null;$out[$slug]=is_numeric($sec)?max(1,(int)round($sec/60)):$fallback[$slug];}return $out;}
function sb6_rank(array $spots,array $p): array {$p=array_replace(cc_surf_profile_defaults(),$p);$p['session_minutes']=max(20,min(180,(int)($p['session_minutes']??40)));$p['buffer_minutes']=max(5,min(45,(int)($p['buffer_minutes']??10)));$p['time_mode']=in_array((string)($p['time_mode']??''),['finish_work','in_water','must_work'],true)?(string)$p['time_mode']:'finish_work';$base=cc_surf_selected_epoch($p);$times=sb6_road_times($spots,$p);$buf=(int)$p['buffer_minutes']*60;$sess=(int)$p['session_minutes']*60;$rows=[];foreach($spots as $s){$tr=$times[(string)$s['slug']]??null;$eval=$base;$plan=['travel'=>$tr,'in_water'=>$base,'leave_base'=>null,'leave_water'=>null,'arrive_back'=>null];if($tr!==null){$road=$tr*60;if($p['time_mode']==='finish_work'){$plan['leave_base']=$base;$plan['in_water']=$base+$road+$buf;$plan['leave_water']=$plan['in_water']+$sess;$plan['arrive_back']=$plan['leave_water']+$road+$buf;$eval=$plan['in_water'];}elseif($p['time_mode']==='in_water'){$plan['in_water']=$base;$plan['leave_base']=$base-$road-$buf;$plan['leave_water']=$base+$sess;$plan['arrive_back']=$plan['leave_water']+$road+$buf;$eval=$base;}else{$plan['arrive_back']=$base;$plan['leave_water']=$base-$road-$buf;$plan['in_water']=$plan['leave_water']-$sess;$plan['leave_base']=$plan['in_water']-$road-$buf;$eval=$plan['in_water']+(int)round($sess/2);}}$h=cc_surf_nearest_hour($s,$eval);if(!$h)continue;$sc=cc_surf_score($s,$h,$p);$rows[]=['spot'=>$s,'hour'=>$h,'score'=>$sc['score'],'travel'=>$tr,'plan'=>$plan];}usort($rows,fn($a,$b)=>$b['score']<=>$a['score']);return [$rows,$p];}
function sb6_clock(?int $epoch): string {if(!$epoch)return '—';return (new DateTimeImmutable('@'.$epoch))->setTimezone(new DateTimeZone('Australia/Brisbane'))->format('g:i A');}
function sb6_plan(array $a,array $p): string {$pl=$a['plan'];$tr=$a['travel'];if($tr===null)return 'Travel not included because no starting area is saved.';if($p['time_mode']==='finish_work')return 'Finish at '.sb6_clock((int)$pl['leave_base']).' → drive ~'.$tr.' min → '.$p['buffer_minutes'].' min setup → in water about '.sb6_clock((int)$pl['in_water']).'.';if($p['time_mode']==='in_water')return 'Leave about '.sb6_clock((int)$pl['leave_base']).' to be in the water at '.sb6_clock((int)$pl['in_water']).'.';return 'Leave about '.sb6_clock((int)$pl['leave_base']).', surf '.sb6_clock((int)$pl['in_water']).'–'.sb6_clock((int)$pl['leave_water']).', back by '.sb6_clock((int)$pl['arrive_back']).'.';}
function sb6_send(string $token,string $to,string $subject,string $html): bool {$url='https://api.mail.hostinger.com/api/v1/mailboxes/AC976a0c9e97ca666ca6966bd72016/send';$payload=['to'=>[$to],'subject'=>$subject,'html'=>$html,'text'=>trim(preg_replace('/\s+/',' ',strip_tags($html))),'displayName'=>'CostaCams'];$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_TIMEOUT=>15,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$token,'Content-Type: application/json','Accept: application/json'],CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)]);$raw=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);return $raw!==false&&$code>=200&&$code<300;}

$tz=new DateTimeZone('Australia/Brisbane');$now=new DateTimeImmutable('now',$tz);$hm=(int)$now->format('Hi');$date=$now->format('Y-m-d');$morning=$hm>=415&&$hm<500;$evening=$hm>=1900&&$hm<1945;if(!$morning&&!$evening){echo "outside_send_window\n";exit;}
$spots=cc_surf_load_spots($pdo);$rows=$pdo->query("SELECT * FROM surf_beta_subscribers WHERE confirmed=1 AND active=1")->fetchAll();$sent=0;$failed=0;
foreach($rows as $r){$freq=(string)$r['email_frequency'];$kind=$morning?'morning':'evening';if($freq!==$kind&&$freq!=='both')continue;$last=$morning?(string)($r['last_morning_date']??''):(string)($r['last_evening_date']??'');if($last===$date)continue;$p=json_decode((string)$r['profile_json'],true);if(!is_array($p))$p=[];$p=array_replace(cc_surf_profile_defaults(),$p);if($r['origin_lat']!==null&&$r['origin_lon']!==null){$p['origin_lat']=(float)$r['origin_lat'];$p['origin_lon']=(float)$r['origin_lon'];}$p['day_offset']=$morning?0:1;[$rank,$p]=sb6_rank($spots,$p);if(!$rank)continue;$top=array_slice($rank,0,3);$a=$top[0];$h=$a['hour'];$list='';foreach($top as $i=>$x){$hh=$x['hour'];$list.='<tr><td style="padding:8px;border-bottom:1px solid #e5e7e8">#'.($i+1).' <b>'.htmlspecialchars((string)$x['spot']['name']).'</b></td><td style="padding:8px;border-bottom:1px solid #e5e7e8">'.(int)$x['score'].'/100</td><td style="padding:8px;border-bottom:1px solid #e5e7e8">'.number_format((float)($hh['wave_height']??0),1).'m · '.round((float)($hh['wave_period']??0)).'s · '.htmlspecialchars((string)($hh['wind_compass']??'—')).' '.round((float)($hh['wind_speed']??0)).'km/h</td></tr>';}$base='https://costacams.com/ccdeploy-v3/costacams-v3/surf-match-beta-v6.php';$email=(string)$r['email'];$manage=$base.'?manage='.rawurlencode(sb6_token((int)$r['id'],$email,'manage'));$unsub=$base.'?unsubscribe='.rawurlencode(sb6_token((int)$r['id'],$email,'unsubscribe'));$dayWord=$morning?'today':'tomorrow';$html='<div style="font-family:Arial,sans-serif;max-width:650px;margin:auto;color:#182126"><p style="font-size:12px;color:#397b8b;font-weight:bold">COSTACAMS SURF BRIEF · '.strtoupper($dayWord).'</p><h1 style="margin-bottom:4px">'.htmlspecialchars((string)$a['spot']['name']).' · '.$a['score'].'/100</h1><p><b>Your plan:</b> '.htmlspecialchars(sb6_plan($a,$p)).'</p><p>🌊 '.number_format((float)($h['wave_height']??0),1).' m · '.round((float)($h['wave_period']??0)).' s &nbsp; ⚡ '.number_format((float)($h['energy_kwm']??0),1).' kW/m &nbsp; 💨 '.htmlspecialchars((string)($h['wind_compass']??'—')).' '.round((float)($h['wind_speed']??0)).' km/h</p><p>☀️ UV '.number_format((float)($h['uv']??0),1).'</p><table style="border-collapse:collapse;width:100%;margin:15px 0">'.$list.'</table><p><a style="display:inline-block;background:#0d6578;color:#fff;text-decoration:none;padding:11px 16px;border-radius:8px" href="'.htmlspecialchars($manage).'">Open & edit my Surf Match</a></p><p style="font-size:11px;color:#778">Forecast guidance only. Check local conditions and surf within your ability.</p><p style="font-size:11px"><a href="'.htmlspecialchars($manage).'">Manage profile</a> · <a href="'.htmlspecialchars($unsub).'">Unsubscribe</a></p></div>';$subject='CostaCams Surf Brief: best match '.$dayWord.' — '.$a['spot']['name'];if(sb6_send($mailToken,$email,$subject,$html)){$field=$morning?'last_morning_date':'last_evening_date';$pdo->prepare("UPDATE surf_beta_subscribers SET $field=?,last_email_at=NOW() WHERE id=?")->execute([$date,(int)$r['id']]);$sent++;}else{$failed++;}}
echo "surf_brief_v6 kind=".($morning?'morning':'evening')." sent=$sent failed=$failed\n";
